using FirepowerLoop.Arcade;

/// <summary>多实例、接力、真实接触及死亡的纯领域检查，使用正式配置。</summary>
internal static class SupportChecks
{
    public static int Run(int max)
    {
        var tables=new Tables(n=>new Luban.ByteBuf(File.ReadAllBytes(Path.Combine("Client/Assets/Game/Config",n+".bytes"))));
        var c=ArcadeSlayerMartConfiguration.FromTables(tables);float P(string id)=>c.Parameter(id);
        ArcadeSlayerMartState State()=>new(){RegionInstanceId="run:slayermart:1",Visit=1,Generation=1,Revision=1,Players=new(){new(){PlayerId=1,Lives=3}}};
        void Grant(ArcadeSlayerMartState s,SlayerMartEffect effect,int amount,float duration=0)
        {s.PendingGrants.Add(new(){EventId=s.RegionInstanceId+":"+(++s.GrantSequence),PlayerId=1,Effect=effect,Amount=amount,Duration=duration});}
        ArcadeSlayerMartState Apply(ArcadeSlayerMartState s,int ordinary=0)
        {Require(ArcadeSlayerMartSupportRules.TryApplyGrants(s,c,new Dictionary<long,int>{{1,ordinary}},out var next,out var error),error);return next;}
        ArcadeSlayerMartState With(SlayerMartEffect effect,int amount,float duration=0)
        {var s=State();Grant(s,effect,amount,duration);return Apply(s);}
        void Advance(ArcadeSlayerMartPlayer p,double seconds,bool active=true)=>ArcadeSlayerMartSupportRules.Advance(p,seconds,active,c.Supports,P);
        bool Contact(ArcadeSlayerMartPlayer p,ArcadeSlayerMartEffectInstance i,string target,float x,float y,float radius=0)
            =>ArcadeSlayerMartSupportRules.TryContact(p,i,target,x,y,radius,0,0,c.Supports,P);
        ArcadeSlayerMartPoint[] Bodies(ArcadeSlayerMartPlayer p,ArcadeSlayerMartEffectInstance i)=>ArcadeSlayerMartSupportRules.Bodies(p,i,0,0,c.Supports,P);
        var tests=new (string,Action)[]{
            ("Three chickens are parallel independent identities",()=>{var s=With(SlayerMartEffect.ChickenPack,3,300);var p=s.Players[0];Require(p.Supports.Count==3&&p.Supports.Select(i=>i.InstanceId).Distinct().Count()==3&&p.Supports.All(i=>i.RemainingSeconds==300));Advance(p,301);Require(p.Supports.Count==0&&p.Chickens==0);}),
            ("Ordinary plus purchased chicken leaves three package slots",()=>{var s=With(SlayerMartEffect.Chicken,1,300);Grant(s,SlayerMartEffect.ChickenPack,3,300);Require(Apply(s,1).Players[0].Chickens==5);}),
            ("Insufficient package capacity changes nothing",()=>{var s=With(SlayerMartEffect.ChickenPack,3,300);Grant(s,SlayerMartEffect.ChickenPack,3,300);Require(!ArcadeSlayerMartSupportRules.TryApplyGrants(s,c,new Dictionary<long,int>{{1,0}},out var n,out _)&&n==null&&s.Players[0].Supports.Count==3);}),
            ("Grant replay cannot refresh lifetime or shots",()=>{var s=With(SlayerMartEffect.ChickenPack,3,300);s.Players[0].Supports[0].RemainingSeconds=7;var n=Apply(s);Require(n.Players[0].Supports.Count==3&&n.Players[0].Supports[0].RemainingSeconds==7);}),
            ("Saw grant lasts five minutes",()=>{var p=With(SlayerMartEffect.Saw,1,300).Players[0];Require(p.Supports.Single().Kind==SlayerMartSupportKind.Saw&&p.Supports.Single().RemainingSeconds==300);}),
            ("Combo barrel remains three charges within five minutes",()=>{var p=With(SlayerMartEffect.SawBarrel,1,300).Players[0];Require(p.Supports.Count==2&&p.Supports.All(i=>i.RemainingSeconds==300)&&p.Supports.Single(i=>i.Kind==SlayerMartSupportKind.Barrel).Charges==3);var s=State();s.Players[0].Owned.Add("slayermart.item.22");Grant(s,SlayerMartEffect.SawBarrel,1,300);Require(Apply(s).Players[0].Supports.Single(i=>i.Kind==SlayerMartSupportKind.Barrel).RemainingSeconds==300);}),
            ("Combo extends saw without resetting consumed barrel charges",()=>{var s=With(SlayerMartEffect.SawBarrel,1,300);s.Players[0].Supports.First(i=>i.Kind==SlayerMartSupportKind.Saw).RemainingSeconds=290;s.Players[0].Supports.First(i=>i.Kind==SlayerMartSupportKind.Barrel).Charges=1;Grant(s,SlayerMartEffect.SawBarrel,1,300);var p=Apply(s).Players[0];Require(p.Supports.Count==2&&p.Supports.First(i=>i.Kind==SlayerMartSupportKind.Saw).RemainingSeconds==300&&p.Supports.First(i=>i.Kind==SlayerMartSupportKind.Barrel).Charges==1);}),
            ("Invalid combo never applies half of a grant",()=>{var s=State();Grant(s,SlayerMartEffect.SawBarrel,1,float.NaN);Require(!ArcadeSlayerMartSupportRules.TryApplyGrants(s,c,new Dictionary<long,int>(),out var n,out _)&&n==null&&s.Players[0].Supports.Count==0);s=State();Grant(s,SlayerMartEffect.SawBarrel,1,0);Require(!ArcadeSlayerMartSupportRules.TryApplyGrants(s,c,new Dictionary<long,int>(),out n,out _)&&n==null);}),
            ("Relay starts one barrel and queues two complete shares",()=>{var p=With(SlayerMartEffect.BarrelRelay,3).Players[0];Require(p.Supports.Count==1&&p.Queues.Single().Waiting.Count==2&&p.Supports[0].Charges==3);}),
            ("Depleted share starts a new identity without refilling old one",()=>{var s=With(SlayerMartEffect.BarrelRelay,3);var p=s.Players[0];var first=p.Supports[0];for(int k=0;k<3;k++){Require(ArcadeSlayerMartSupportRules.TryTriggerBarrel(first,true,c.Supports));if(k<2)Advance(p,.45);}Grant(s,SlayerMartEffect.BarrelRelay,3);var newPack=Apply(s).Players[0];Advance(newPack,0);Require(newPack.Supports.Count(i=>i.Kind==SlayerMartSupportKind.Barrel)==1&&newPack.Queues.Count==1&&newPack.Queues[0].Waiting.Count==4);Advance(p,0);Require(first.Charges==0&&p.Supports[0].InstanceId!=first.InstanceId&&p.Supports[0].Charges==3&&p.Queues[0].Waiting.Count==1);}),
            ("Frozen clock never consumes active queue or phase",()=>{var p=With(SlayerMartEffect.BarrelRelay,3).Players[0];Advance(p,100,false);Require(p.Supports[0].RemainingSeconds==c.Supports.Get(SlayerMartSupportKind.Barrel).Duration&&p.Queues[0].Waiting.Count==2&&p.Supports[0].Phase==0);}),
            ("Long frame starts only next share at full lifetime",()=>{var p=With(SlayerMartEffect.BarrelRelay,3).Players[0];Advance(p,1000);Require(p.Supports.Count==1&&p.Queues[0].Waiting.Count==1&&p.Supports[0].RemainingSeconds==c.Supports.Get(SlayerMartSupportKind.Barrel).Duration&&p.Supports[0].CooldownSeconds>0);}),
            ("Clone preserves phase remaining and spent charges",()=>{var s=With(SlayerMartEffect.BarrelRelay,3);Advance(s.Players[0],1);s.Players[0].Supports[0].Charges=1;var clone=s.Clone();s.Players[0].Supports[0].Phase=0;s.Players[0].Queues[0].Waiting.Clear();Require(clone.Players[0].Supports[0].Phase>0&&clone.Players[0].Supports[0].Charges==1&&clone.Players[0].Queues[0].Waiting.Count==2);Require(ArcadeSlayerMartSupportRules.IsValid(clone.Players[0],c));clone.Players[0].Supports[0].Phase=double.NaN;Require(!ArcadeSlayerMartSupportRules.IsValid(clone.Players[0],c));clone.Players[0].Supports[0].Phase=0;clone.Players[0].Supports[0].ShotDirectionX=float.NaN;Require(!ArcadeSlayerMartSupportRules.IsValid(clone.Players[0],c));}),
            ("Prior visit replay retains stable source identity",()=>{var s=With(SlayerMartEffect.Chicken,1,300);var id=s.Players[0].Supports[0].InstanceId;s.Visit=2;s.RegionInstanceId="run:slayermart:2";Require(Apply(s).Players[0].Supports[0].InstanceId==id);}),
            ("Three Tesla balls share group and distinct phases",()=>{var p=With(SlayerMartEffect.TeslaPack,3).Players[0];Require(p.Supports.Count==3&&p.Supports.Select(i=>i.GroupId).Distinct().Count()==1&&p.Supports.Select(i=>i.Phase).Distinct().Count()==3);}),
            ("Tesla lifetime uses original ordinary drop",()=>{var p=With(SlayerMartEffect.TeslaPack,3).Players[0];Require(p.Supports.All(i=>i.RemainingSeconds==c.Supports.Get(SlayerMartSupportKind.Orb).Duration));}),
            ("Orbit body contact never damages empty ring center",()=>{var p=With(SlayerMartEffect.TeslaPack,3).Players[0];var i=p.Supports[0];Require(!Contact(p,i,"map:1",0,0));var pos=Bodies(p,i)[0];Require(Contact(p,i,"map:1",pos.X,pos.Y));}),
            ("Three balls share same target cooldown",()=>{var p=With(SlayerMartEffect.TeslaPack,3).Players[0];foreach(var i in p.Supports)i.Phase=0;var pos=Bodies(p,p.Supports[0])[0];Require(Contact(p,p.Supports[0],"map:1",pos.X,pos.Y));Require(!Contact(p,p.Supports[1],"map:1",pos.X,pos.Y));Advance(p,c.Supports.Get(SlayerMartSupportKind.Orb).Interval);pos=Bodies(p,p.Supports[1])[0];Require(Contact(p,p.Supports[1],"map:1",pos.X,pos.Y));}),
            ("Different targets each receive one hit",()=>{var p=With(SlayerMartEffect.TeslaPack,3).Players[0];var i=p.Supports[0];var pos=Bodies(p,i)[0];Require(Contact(p,i,"map:1",pos.X,pos.Y)&&Contact(p,i,"map:2",pos.X,pos.Y));}),
            ("Single saw only has its actual contact body",()=>{var p=With(SlayerMartEffect.Saw,1,300).Players[0];var i=p.Supports[0];var pos=Bodies(p,i).Single();Require(Math.Abs(pos.X-c.Supports.Get(SlayerMartSupportKind.Saw).Radius)<.001&&!Contact(p,i,"map:1",-pos.X,-pos.Y));}),
            ("Saw mastery adds opposite body at doubled distance",()=>{var p=With(SlayerMartEffect.Saw,1,300).Players[0];p.Owned.Add("slayermart.item.11");var points=Bodies(p,p.Supports[0]);Require(points.Length==2&&Math.Abs(points[0].X-c.Supports.Get(SlayerMartSupportKind.Saw).Radius*2)<.001&&Math.Abs(points[0].X+points[1].X)<.001);}),
            ("Double saw bodies cannot double hit same enemy",()=>{var p=With(SlayerMartEffect.Saw,1,300).Players[0];p.Owned.Add("slayermart.item.11");var i=p.Supports[0];Require(Contact(p,i,"map:1",0,0,10)&&!Contact(p,i,"map:1",0,0,10));}),
            ("Each chicken fires on its own cooldown",()=>{var p=With(SlayerMartEffect.ChickenPack,3,300).Players[0];Require(p.Supports.All(i=>ArcadeSlayerMartSupportRules.TryShoot(i,c.Supports)));Require(p.Supports.All(i=>!ArcadeSlayerMartSupportRules.TryShoot(i,c.Supports)));Advance(p,c.Supports.Get(SlayerMartSupportKind.Chicken).Interval);Require(p.Supports.All(i=>ArcadeSlayerMartSupportRules.TryShoot(i,c.Supports)));}),
            ("Death clears supports and queue but preserves applied receipts",()=>{var s=With(SlayerMartEffect.BarrelRelay,3);var p=s.Players[0];p.VestSlots=2;p.Plates=2;p.StormCharge=99;ArcadeSlayerMartAbilityRules.OnDeath(p);Require(p.Supports.Count==0&&p.Queues.Count==0&&p.SupportHits.Count==0&&p.Plates==0&&p.VestSlots==2&&p.StormCharge==99&&Apply(s).Players[0].Supports.Count==0);})
        };
        if(tests.Length>max)throw new InvalidOperationException("Test limit exceeded");int failed=0;
        foreach(var(name,test)in tests)try{test();Console.WriteLine("PASS SlayerMartSupportTests."+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL SlayerMartSupportTests."+name+": "+ex.Message);}
        Console.WriteLine($"{tests.Length-failed}/{tests.Length} passed");return failed==0?0:1;
    }
    private static void Require(bool value,string message=null){if(!value)throw new InvalidOperationException(message??"Support contract violated");}
}
